<template>
  <div class="min-h-screen bg-[#f7f8fa] p-5 md:p-7">
    <div class="mb-6 flex flex-wrap items-start justify-between gap-3">
      <div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-blue-600">SumashDesk workspace</p><h1 class="mt-1 text-2xl font-bold tracking-tight text-slate-900">{{ title }}</h1><p class="mt-1 text-sm text-slate-500">{{ subtitle }}</p></div>
      <button @click="openCreate" class="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2.5 text-xs font-semibold text-white shadow-sm hover:bg-blue-700"><Plus class="h-4 w-4"/> {{ actionLabel }}</button>
    </div>
    <div class="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><div v-for="stat in stats" :key="stat.label" class="rounded-xl border border-slate-200 bg-white p-4"><p class="text-[11px] font-medium text-slate-500">{{ stat.label }}</p><div class="mt-2 flex items-end justify-between"><p class="text-2xl font-bold text-slate-900">{{ stat.value }}</p><span class="rounded-md bg-emerald-50 px-2 py-1 text-[10px] font-semibold text-emerald-700">{{ stat.note || 'Overview' }}</span></div></div></div>
    <div class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-4"><div class="relative min-w-[220px] flex-1 sm:max-w-sm"><Search class="absolute left-3 top-2.5 h-4 w-4 text-slate-400"/><input v-model="search" :placeholder="searchPlaceholder" class="h-9 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-xs outline-none focus:border-blue-400 focus:bg-white"/></div><div class="flex items-center gap-2"><select v-model="filter" class="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs text-slate-600"><option>All</option><option v-for="f in filters" :key="f">{{ f }}</option></select><label v-if="importEnabled" class="flex h-9 cursor-pointer items-center gap-2 rounded-lg border border-slate-200 px-3 text-xs font-semibold text-slate-600 hover:bg-slate-50"><Upload class="h-3.5 w-3.5"/> Import CSV<input type="file" accept=".csv,text/csv" class="hidden" @change="importRows"/></label><button @click="exportRows" class="flex h-9 items-center gap-2 rounded-lg border border-slate-200 px-3 text-xs font-semibold text-slate-600 hover:bg-slate-50"><Download class="h-3.5 w-3.5"/> Export CSV</button></div></div>
      <div class="overflow-x-auto"><table class="w-full min-w-[680px] text-left"><thead class="bg-slate-50"><tr><th v-for="col in columns" :key="col" class="px-4 py-3 text-[10px] font-bold uppercase tracking-wide text-slate-500">{{ col }}</th><th class="px-4 py-3 text-right text-[10px] font-bold uppercase tracking-wide text-slate-500">Actions</th></tr></thead><tbody><tr v-for="item in filteredRows" :key="item.index" class="border-t border-slate-100 hover:bg-slate-50/70"><td v-for="(value,j) in item.row" :key="j" class="px-4 py-3 text-xs text-slate-700"><span v-if="j===0" class="font-semibold text-slate-900">{{ value }}</span><span v-else-if="isPositive(value)" class="rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-semibold text-emerald-700">{{ value }}</span><span v-else-if="isNegative(value)" class="rounded-full bg-rose-50 px-2 py-1 text-[10px] font-semibold text-rose-700">{{ value }}</span><span v-else>{{ value }}</span></td><td class="px-4 py-3 text-right"><button @click="viewRow(item.row)" title="View" class="rounded-md p-1.5 text-slate-400 hover:bg-slate-100 hover:text-slate-700"><Eye class="h-3.5 w-3.5"/></button><button @click="editRow(item.index)" title="Edit" class="rounded-md p-1.5 text-slate-400 hover:bg-blue-50 hover:text-blue-600"><Pencil class="h-3.5 w-3.5"/></button><button @click="removeRow(item.index)" title="Delete" class="rounded-md p-1.5 text-slate-400 hover:bg-rose-50 hover:text-rose-600"><Trash2 class="h-3.5 w-3.5"/></button></td></tr><tr v-if="!filteredRows.length"><td :colspan="columns.length+1" class="p-10 text-center text-xs text-slate-400">No records found. Create a new record to get started.</td></tr></tbody></table></div>
      <div class="flex items-center justify-between border-t border-slate-100 px-4 py-3 text-[10px] text-slate-500"><span>Showing {{ filteredRows.length }} of {{ rows.length }} records</span><span>Demo data · Changes are saved in this browser</span></div>
    </div>
    <div v-if="modal" class="fixed inset-0 z-50 grid place-items-center bg-slate-900/35 p-4" @click.self="modal=false"><div class="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-5 shadow-2xl"><div class="flex items-center justify-between"><div><h2 class="text-base font-bold">{{ editingIndex===null ? actionLabel : 'Edit record' }}</h2><p class="mt-1 text-[11px] text-slate-500">Update the {{ title.toLowerCase() }} demo data.</p></div><button @click="modal=false" class="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100"><X class="h-4 w-4"/></button></div><div class="mt-4 grid gap-3 sm:grid-cols-2"><label v-for="(col,i) in columns" :key="col" class="block text-[11px] font-semibold text-slate-600" :class="i===columns.length-1?'sm:col-span-2':''">{{ col }}<select v-if="optionsFor(col).length" v-model="form[i]" class="mt-1.5 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs font-normal outline-none focus:border-blue-400"><option value="">Select {{ col.toLowerCase() }}</option><option v-for="option in optionsFor(col)" :key="option">{{ option }}</option></select><textarea v-else-if="col.toLowerCase().includes('message') || col.toLowerCase().includes('description')" v-model="form[i]" rows="3" :placeholder="`Enter ${col.toLowerCase()}`" class="mt-1.5 w-full rounded-lg border border-slate-200 px-3 py-2 text-xs font-normal outline-none focus:border-blue-400"/><input v-else v-model="form[i]" :placeholder="`Enter ${col.toLowerCase()}`" class="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-xs font-normal outline-none focus:border-blue-400"/></label></div><div class="mt-5 flex justify-end gap-2 border-t border-slate-100 pt-4"><button @click="modal=false" class="rounded-lg border border-slate-200 px-4 py-2 text-xs font-semibold text-slate-600">Cancel</button><button @click="save" class="rounded-lg bg-blue-600 px-4 py-2 text-xs font-semibold text-white hover:bg-blue-700">Save changes</button></div></div></div>
    <div v-if="detailRow" class="fixed inset-0 z-50 flex justify-end bg-slate-900/25" @click.self="detailRow=null"><aside class="h-full w-full max-w-md overflow-y-auto bg-white p-6 shadow-2xl"><div class="flex items-center justify-between"><h2 class="text-base font-bold">{{ title }} details</h2><button @click="detailRow=null" class="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X class="h-4 w-4"/></button></div><div class="mt-5 divide-y divide-slate-100 rounded-xl border border-slate-200"> <div v-for="(value,i) in detailRow" :key="i" class="p-3"><p class="text-[10px] font-semibold uppercase text-slate-400">{{ columns[i] }}</p><p class="mt-1 whitespace-pre-wrap text-sm text-slate-800">{{ value || '—' }}</p></div></div></aside></div>
    <div v-if="toast" class="fixed bottom-5 right-5 z-[60] rounded-xl bg-slate-900 px-4 py-3 text-xs font-medium text-white shadow-xl">{{ toast }}</div>
  </div>
</template>
<script setup lang="ts">
import { computed, ref, onMounted, watch } from 'vue'
import { Plus, Search, Download, Pencil, Trash2, X, Eye, Upload } from '@lucide/vue'
const props = withDefaults(defineProps<{title:string;subtitle:string;actionLabel:string;columns:string[];initialRows:string[][];stats:{label:string;value:string;note?:string}[];filters?:string[];searchPlaceholder?:string;importEnabled?:boolean}>(), { importEnabled: false })
const stateKey = `sumashdesk-records-${props.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`
const rows = useState<string[][]>(stateKey, () => props.initialRows.map(row => [...row]))
onMounted(()=>{const saved=localStorage.getItem(stateKey);if(saved){try{rows.value=JSON.parse(saved) as string[][]}catch{localStorage.removeItem(stateKey)}}})
watch(rows,value=>{if(import.meta.client)localStorage.setItem(stateKey,JSON.stringify(value))},{deep:true})
const search=ref(''),filter=ref('All'),modal=ref(false),form=ref<string[]>([]),editingIndex=ref<number|null>(null),toast=ref(''),detailRow=ref<string[]|null>(null)
const filteredRows=computed(()=>rows.value.map((row,index)=>({row,index})).filter(({row})=>row.join(' ').toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='All'||row.some(v=>v.toLowerCase()===filter.value.toLowerCase()))))
function optionsFor(column:string):string[]{const key=column.toLowerCase();if(key.includes('status'))return ['Active','Inactive','Draft','Scheduled','Running','Completed','Approved','Pending','Rejected','Open','Resolved'];if(key==='role')return ['Admin','Manager','Agent'];if(key.includes('availability'))return ['Online','Busy','Offline'];if(key.includes('opt-in'))return ['Yes','No'];if(key.includes('category'))return ['Greeting','Delivery','Payment','Support','General','Marketing','Utility','Authentication'];if(key.includes('language'))return ['English','Bengali'];if(key==='group'||key==='recipient group'||key==='audience')return ['VIP Customers','Interested Leads','New Customers','Support Follow-up','All opted-in contacts'];if(key.includes('priority'))return ['Low','Normal','High'];if(key==='template')return ['order_update','welcome_customer','payment_reminder','login_code'];return []}
function isPositive(value:string){return /^(active|approved|completed|delivered|online|connected)$/i.test(value)}
function isNegative(value:string){return /^(inactive|rejected|failed|offline|disconnected)$/i.test(value)}
function openCreate(){editingIndex.value=null;form.value=props.columns.map(()=> '');modal.value=true}
function editRow(index:number){editingIndex.value=index;form.value=[...rows.value[index]];modal.value=true}
function viewRow(row:string[]){detailRow.value=[...row]}
function save(){if(!form.value[0]?.trim()){notify('Please enter the required name');return}if(editingIndex.value===null)rows.value.unshift([...form.value]);else rows.value[editingIndex.value]=[...form.value];modal.value=false;notify('Changes saved successfully')}
function removeRow(index:number){if(!confirm('Delete this record? This only changes the local demo data.'))return;rows.value.splice(index,1);notify('Record deleted')}
async function importRows(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;const text=await file.text();const parsed=text.split(/\r?\n/).filter(Boolean).slice(1).map(line=>line.split(',').map(value=>value.trim().replace(/^"|"$/g,''))).filter(row=>row.length===props.columns.length);rows.value.unshift(...parsed);input.value='';notify(`${parsed.length} records imported`)}
function exportRows(){const csv=[props.columns,...filteredRows.value.map(item=>item.row)].map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`${props.title.toLowerCase().replaceAll(' ','-')}.csv`;a.click();URL.revokeObjectURL(a.href);notify('CSV exported')}
function notify(message:string){toast.value=message;setTimeout(()=>toast.value='',2200)}
</script>
